INSERT INTO player_behavior_logs (
    account_id, account, nickname, guest, platform, client_uuid,
    ip, region, action, sub_action, protocol, result_status,
    error_message, request_body_json, related_type, related_id, created_at
) VALUES (
    #{accountId}, #{account}, #{nickname}, #{guest}, #{platform}, #{clientUuid},
    #{ip}, #{region}, #{action}, #{subAction}, #{protocol}, #{resultStatus},
    #{errorMessage}, #{requestBodyJson}, #{relatedType}, #{relatedId}, #{createdAt}
)

sql.where:
AND action NOT IN ('LIST_USERS', 'LIST_FRIENDS', 'LIST_FRIEND_REQUESTS', 'PULL_HISTORY', 'COUNT_HISTORY')

    AND account LIKE '%' || #{account} || '%'


    AND nickname LIKE '%' || #{nickname} || '%'


    AND ip LIKE '%' || #{ip} || '%'


    AND platform = #{platform}


    AND action = #{action}


    AND sub_action LIKE '%' || #{subAction} || '%'


    AND result_status = #{resultStatus}


    AND created_at >= #{startAt}


    AND created_at <= #{endAt}
